"""IntentAgent: generated by G2C for E2A v1.2; completed by hand.

Classifies the request (INVESTIGATE, EXPLAIN, PROPOSE, POLICY, UNSUPPORTED) and extracts the identifiers
it names. An identifier the model returns is kept only if it appears in the request itself: the
model cannot invent the record to look at. When the model is unavailable or its answer is not
valid, the fallback classifies with plain rules (degraded), so investigations keep working."""
import json
import logging
import os
import re

from e2a import BaseAgent
from pydantic import ValidationError

from ..services.evidence import LINE_ID, ORDER_ID, SETTLEMENT_ID
from .intent_agent_output import IntentAgentOutput

SYSTEM = ("You are IntentAgent. Classify a finance investigator's request into one intent: INVESTIGATE (why a "
          "payment or bank line is unmatched), EXPLAIN (why a settlement is delayed, failed or flagged), PROPOSE (a "
          "write-off or refund), POLICY (a question about the rules, limits, terms or procedures, naming no record) or "
          "UNSUPPORTED. Extract line_id, settlement_id and order_id only if the request "
          'states them. Answer as JSON {"intent": ..., "line_id": ..., "settlement_id": ..., "order_id": ...}.')


def json_object(text: str) -> dict:
    """The JSON object in a model reply: plain JSON, or wrapped in a code fence or a sentence (live finding,
    GCP-01: Gemini answers ```json {...} ``` even when asked for JSON)."""
    text = (text or "").strip()
    try:
        return json.loads(text)
    except ValueError:
        start, end = text.find("{"), text.rfind("}")
        if start < 0 or end <= start:
            raise
        return json.loads(text[start:end + 1])


def clean_id(value, query: str):
    """An identifier the model returned, without the punctuation of the sentence around it ("ORD-7Q2K9X4M1B?" is
    "ORD-7Q2K9X4M1B"), kept only if it is in the request itself (live finding, GCP-01)."""
    if not isinstance(value, str):
        return None
    value = value.strip().strip(".,;:!?()[]{}\"'`")
    return value if value and value in query else None


POLICY_WORDS = re.compile(r"\b(policy|policies|limits?|thresholds?|procedures?|process|terms|allowed|permitted|"
                          r"expires?|expiry|disputes?|chargebacks?|fees?|approvers?|approval|four[- ]eyes|rules?|"
                          r"short payments?|overpayments?)\b")


def rule_intent(text: str) -> dict:
    """The deterministic reading of a request (the fallback, and the simulated model)."""
    low = text.lower()
    found = {"line_id": (LINE_ID.search(text) or [None, None])[1],
             "settlement_id": (SETTLEMENT_ID.search(text) or [None])[0],
             "order_id": (ORDER_ID.search(text) or [None])[0]}
    if not any(found.values()):
        intent = "POLICY" if POLICY_WORDS.search(low) else "UNSUPPORTED"
    elif re.search(r"\b(propose|write[- ]?off|refund|adjust)", low):
        intent = "PROPOSE"
    elif found["line_id"] or re.search(r"unmatched|exception|reconcil", low):
        intent = "INVESTIGATE"
    else:
        intent = "EXPLAIN"
    return {"intent": intent, **{k: v for k, v in found.items() if v}}


def sure_intent(text: str):
    """The rules' reading of a request when it is unambiguous, else None (the model is then asked).

    Unambiguous means a record id the request itself states AND the words that make the intent plain: a proposal
    (write-off, refund, adjust, propose), an unmatched bank line, or a question about a settlement or order. Reading
    these by rule instead of asking the model saves one of the two or three model calls of a request (12 to 23% of the
    tokens on the simulated model; the live figures are in docs/EVALUATION_REPORT.md once measured) and cannot be wrong in the dangerous direction: the identifiers
    are the ones in the text, and a proposal still waits for a second person. GENAI_INTENT_BY_RULES=false turns it
    off, to compare."""
    if os.getenv("GENAI_INTENT_BY_RULES", "true").lower() == "false":
        return None
    ruled = rule_intent(text)
    if ruled["intent"] == "POLICY":
        return ruled if re.search(r"\b(what|how|which|who|when)\b", text.lower()) else None
    if ruled["intent"] == "UNSUPPORTED":
        return None
    low = text.lower()
    plain = (re.search(r"\b(propose|write[- ]?off|refund|adjust)", low)
             or re.search(r"unmatched|exception|reconcil", low)
             or re.search(r"\b(why|explain|status|delayed|failed|flagged|declined|paid)\b", low))
    return ruled if plain else None


class IntentAgent(BaseAgent):
    agent_name = 'IntentAgent'

    def _build_messages(self, state, ctx):
        sure = sure_intent(str(state.get('query', '')))
        if sure is not None:                       # no model step: the request says what it wants
            state.update(sure)
            state['intent_by'] = 'rules'
            return None
        return [{'role': 'system', 'content': SYSTEM},
                {'role': 'user', 'content': str(state.get('query', ''))}]

    def _evaluate_output(self, response, state, ctx):
        """Accept the model output only if it is valid; 0.0 sends the request to _fallback."""
        text = (response or {}).get('text', '') if isinstance(response, dict) else str(response or '')
        try:
            data = IntentAgentOutput.model_validate(json_object(text)).model_dump(mode="json")
        except (ValueError, ValidationError):
            # An unreadable reply must not end the investigation (a fallback ends the workflow): read the request
            # with the rules, mark the run degraded, and accept that reading so the evidence step still runs.
            state.update(rule_intent(str(state.get('query', ''))))
            state['degraded'] = True
            return 1.0
        query = str(state.get('query', ''))
        for key in ('line_id', 'settlement_id', 'order_id'):          # only what the request says
            data[key] = clean_id(data.get(key), query)
        if data['intent'] not in ('UNSUPPORTED', 'POLICY') and not any(data.get(k) for k in ('line_id', 'settlement_id', 'order_id')):
            data['intent'] = 'UNSUPPORTED'                           # nothing to look at
        if data['intent'] == 'UNSUPPORTED':
            # The model found nothing to do. If the request itself names a bank line, settlement or order, the rules
            # read it deterministically; a small free-tier model sometimes answers UNSUPPORTED to a plain
            # "Status of order ORD-...?" (live finding, GCP-01). Investigating is read-only; a proposal still waits
            # for a second person.
            ruled = rule_intent(query)
            if ruled['intent'] != 'UNSUPPORTED':
                data = {**data, **{k: ruled.get(k) for k in ('line_id', 'settlement_id', 'order_id')},
                        'intent': ruled['intent']}
                state['degraded'] = True
        state.update({k: v for k, v in data.items() if v is not None})
        return 1.0

    def _fallback(self, state, ctx):
        state.update(rule_intent(str(state.get('query', ''))))
        state['degraded'] = True
        return {'text': json.dumps({'intent': state['intent']}), 'degraded': True}

    def _handle_error(self, error, state, ctx):
        """The model failed (quota, timeout, refusal): classify with the rules instead (degraded)."""
        logging.warning(f'[IntentAgent] model unavailable, rules used: {error}')
        state.setdefault('model_errors', []).append(str(error))
        self._fallback(state, ctx)
